/* Five-letter word data for Carryover.
   VALID  = every accepted word (wide list, used only to judge submissions)
   COMMON = curated everyday words (used for seeds and for the "words fit" count) */
(function(){
var v="";
var c="";
var VALID=new Set(),COMMON=[];
for(var i=0;i<v.length;i+=5)VALID.add(v.substr(i,5));
for(var j=0;j<c.length;j+=5)COMMON.push(c.substr(j,5));
window.WORDS={VALID:VALID,COMMON:COMMON,COMMON_SET:new Set(COMMON)};
})();
